## 3. Realistische Code-Beispiele

### Beispiel 1: Grundlegende Tabelle mit Sortierung
```tsx
import { DataTable } from '@company/design-system';

interface User {
  id: number;
  name: string;
  email: string;
  role: 'admin' | 'user';
  lastLogin: Date;
}

const users: User[] = [
  { id: 1, name: 'John Doe', email: 'john@example.com', role: 'admin', lastLogin: new Date('2023-01-15') },
  { id: 2, name: 'Jane Smith', email: 'jane@example.com', role: 'user', lastLogin: new Date('2023-02-20') },
];

const columns = [
  { key: 'name', header: 'Name', sortable: true },
  { key: 'email', header: 'Email' },
  {
    key: 'role',
    header: 'Role',
    render: (value: string) => (
      <span style={{ color: value === 'admin' ? 'red' : 'blue' }}>
        {value.toUpperCase()}
      </span>
    )
  },
  {
    key: 'lastLogin',
    header: 'Last Login',
    render: (value: Date) => value.toLocaleDateString()
  }
];

function UserTable() {
  return (
    <DataTable
      data={users}
      columns={columns}
      sortable
      onRowClick={(row) => console.log('Row clicked:', row)}
    />
  );
}
```

### Beispiel 2: Tabelle mit Pagination und benutzerdefiniertem Leerzustand
```tsx
import { DataTable } from '@company/design-system';

interface Product {
  id: string;
  name: string;
  price: number;
  stock: number;
  category: string;
}

const products: Product[] = []; // Empty array for demonstration

const columns = [
  { key: 'name', header: 'Product Name', sortable: true },
  { key: 'price', header: 'Price ($)', sortable: true },
  { key: 'stock', header: 'In Stock' },
  { key: 'category', header: 'Category' }
];

function ProductTable() {
  return (
    <DataTable
      data={products}
      columns={columns}
      pagination
      pageSize={5}
      emptyState={
        <div style={{ padding: '2rem', textAlign: 'center' }}>
          <h3>No products found</h3>
          <p>Try adjusting your search filters</p>
          <button onClick={() => console.log('Reset filters')}>
            Reset Filters
          </button>
        </div>
      }
    />
  );
}
```

### Beispiel 3: Komplexe Tabelle mit allen Features
```tsx
import { DataTable } from '@company/design-system';

interface Order {
  id: string;
  customer: string;
  date: Date;
  amount: number;
  status: 'pending' | 'completed' | 'cancelled';
  items: number;
}

const orders: Order[] = [
  // ... large dataset
];

const columns = [
  { key: 'id', header: 'Order ID', width: 120 },
  { key: 'customer', header: 'Customer', sortable: true },
  {
    key: 'date',
    header: 'Order Date',
    sortable: true,
    render: (value: Date) => value.toLocaleString()
  },
  {
    key: 'amount',
    header: 'Amount ($)',
    sortable: true,
    render: (value: number) => value.toFixed(2)
  },
  {
    key: 'status',
    header: 'Status',
    render: (value: string) => (
      <span style={{
        color: value === 'completed' ? 'green' :
              value === 'pending' ? 'orange' : 'red'
      }}>
        {value.toUpperCase()}
      </span>
    )
  },
  { key: 'items', header: 'Items' }
];

function OrderTable() {
  return (
    <DataTable
      data={orders}
      columns={columns}
      sortable
      pagination
      pageSize={20}
      striped
      stickyHeader
      loading={isLoading}
      onRowClick={(order) => navigateToOrderDetail(order.id)}
    />
  );
}
```

